CREATE TABLE IF NOT EXISTS SchemaMigrations (Version INT PRIMARY KEY, AppliedAt VARCHAR(40) NOT NULL);
CREATE TABLE IF NOT EXISTS Projects (Id VARCHAR(100) PRIMARY KEY, Name VARCHAR(255) NOT NULL, CreatedAt VARCHAR(40) NOT NULL);
CREATE TABLE IF NOT EXISTS Scenes (Id VARCHAR(100) PRIMARY KEY, ProjectId VARCHAR(100) NOT NULL, Revision BIGINT NOT NULL, Document LONGTEXT NOT NULL, PublishedVersionId VARCHAR(100) NULL, UpdatedAt VARCHAR(40) NOT NULL, FOREIGN KEY (ProjectId) REFERENCES Projects(Id), INDEX(ProjectId));
CREATE TABLE IF NOT EXISTS Assets (Id VARCHAR(100) PRIMARY KEY, Name VARCHAR(255) NOT NULL, Kind VARCHAR(20) NOT NULL, Entry VARCHAR(1024) NOT NULL, FilesJson LONGTEXT NOT NULL, Sha256 CHAR(64) NOT NULL, Status VARCHAR(20) NOT NULL, CreatedAt VARCHAR(40) NOT NULL);
CREATE TABLE IF NOT EXISTS Versions (Id VARCHAR(100) PRIMARY KEY, SceneId VARCHAR(100) NOT NULL, Document LONGTEXT NOT NULL, ManifestKey VARCHAR(255) NOT NULL, CreatedAt VARCHAR(40) NOT NULL, Published BOOLEAN NOT NULL, FOREIGN KEY(SceneId) REFERENCES Scenes(Id), INDEX(SceneId));
CREATE TABLE IF NOT EXISTS Dependencies (OwnerType VARCHAR(10) NOT NULL, OwnerId VARCHAR(100) NOT NULL, AssetId VARCHAR(100) NOT NULL, PRIMARY KEY(OwnerType,OwnerId,AssetId), INDEX(AssetId));
